contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticketAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticketAmount)); require(ticketAmount <= 1000000000000000000000000000000);
        require(ticketAmount == 10, "ticketAmount must equal TICKET_AMOUNT");
        require(address(this).balance >= ticketAmount, "insufficient balance");

        uint beforeBalance = address(c).balance;
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;

        c.play{value: ticketAmount}(); if (__ESBMC_reverted()) return;

        uint afterBalance = address(c).balance;
        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;

        assert(
            afterPot == 0 || afterPot == beforePot + ticketAmount
        );
    }

    receive() external payable {}
}

