contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticketAmount) internal {
        ticketAmount = bound(ticketAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticketAmount = 10;
        vm.assume(address(this).balance >= ticketAmount);
        uint beforeBalance = address(c).balance;
        uint256 beforePot;
        try c.pot() returns (uint256 __r) { beforePot = __r; } catch { return; }
        try c.play{value: ticketAmount}() {} catch { return; }
        uint afterBalance = address(c).balance;
        uint256 afterPot;
        try c.pot() returns (uint256 __r) { afterPot = __r; } catch { return; }
        assertTrue(afterPot == 0 || afterPot == beforePot + ticketAmount);
    }

    function testFuzz_run(uint256 ticketAmount) public {
        _run(ticketAmount);
    }

    receive() external payable {}
}
